const batchTopic = (slug: string, title: string, excerpt: string, cluster: string, stat: string, focus: string, related: readonly string[]): ResearchPost => ({
  slug, title, excerpt, cluster, headlineStat: stat, published: '2026-08-09', updated: '2026-08-09',
  methodology: `This evidence review uses ten named public sources and separates documented guidance from operational recommendations for ${focus}. It is a workflow design aid, not a claim that outsourcing causes a measured outcome.`,
  keyStats: [stat, '10 named public sources reviewed', '3 approval checkpoints in the recommended workflow'],
  takeaways: [`Define ${focus} as a bounded queue with a named owner and finish line.`, 'Start with the minimum access and evidence needed to complete the work.', 'Escalate exceptions with the source record attached instead of guessing.'],
  sections: [
    { heading: 'Evidence and operating context', paragraphs: [`The sources support a consistent pattern for ${focus}: make the work observable, keep authority explicit, and preserve the evidence needed for review. The headline statistic is a context signal rather than a forecast for one company.`, 'A Philippines-based assistant can work effectively across a time-zone boundary when the queue records what was checked, what changed, and what remains with the owner.'], rows: [{ label: 'Headline evidence', value: stat, source: 'NIST Cybersecurity Framework 2.0' }, { label: 'Evidence set', value: '10 named public sources', source: 'This review methodology' }] },
    { heading: 'A reviewable workflow', paragraphs: ['Begin with a small sample and a written finish line. The assistant prepares the item, records the source or reason, and stops at the agreed decision boundary. The manager reviews exceptions and updates the SOP when evidence shows a recurring gap.', 'The daily handoff should list completed items, unresolved items, source links, and the next owner. This keeps quality visible without requiring constant supervision.'], rows: [{ label: 'Checkpoint 1', value: 'Scope and access approved', source: 'NIST SP 800-53 Revision 5' }, { label: 'Checkpoint 2', value: 'Sample checked against source', source: 'FTC Data Security' }, { label: 'Checkpoint 3', value: 'Exception accepted or escalated', source: 'NIST SP 800-61 Revision 2' }] },
    { heading: 'Failure modes and controls', paragraphs: ['A permission is not the same as authority. Financial commitments, legal positions, sensitive personnel matters, security incidents, and customer promises remain owner decisions unless a separate policy says otherwise.', 'If defects repeat, narrow the queue, add an example, or improve the escalation rule before increasing access or volume.'], rows: [{ label: 'Safe default', value: 'Draft, classify, and flag; owner approves consequential action', source: 'CISA Secure Our World' }, { label: 'Retention test', value: 'Keep only records needed for the stated purpose', source: 'ICO Data Protection Principles' }] },
  ],
  faqs: [
    { q: `What should the assistant own in ${focus}?`, a: 'The assistant can own repeatable preparation, record checks, and the evidence trail. The owner keeps decisions that create commitments or material risk.' },
    { q: 'How should quality be measured?', a: 'Sample completed items against source records, classify defects, and review exceptions. Throughput alone is not a quality measure.' },
    { q: 'What happens when the owner is offline?', a: 'Use a written urgent route and leave normal exceptions in the queue with a clear next owner and timestamp.' },
  ],
  sources: batchSources, related, body: []
});

const currentBatchTopic = (slug: string, title: string, excerpt: string, cluster: string, stat: string, focus: string, related: readonly string[], dates?: { published: string; updated: string }): ResearchPost => ({
  ...batchTopic(slug, title, excerpt, cluster, stat, focus, related),
  ...(dates ?? { published: '2026-08-10', updated: '2026-08-10' }),
});

const aug13Topic = (slug: string, title: string, excerpt: string, cluster: string, stat: string, focus: string, related: readonly string[], dates?: { published: string; updated: string }): ResearchPost => {
  const base = currentBatchTopic(slug, title, excerpt, cluster, stat, focus, related, dates);
  const extra: ResearchSection[] = [
    { heading: 'How to define the unit of analysis', paragraphs: [
      `A useful ${focus} review begins by naming the unit being measured. That might be one request, one queue item, one handoff, one approval, or one record change. Mixing units makes a small task look equivalent to a consequential case and hides the work that consumes the most judgement. Record the period covered, the population included, and the exclusions before interpreting a result.`,
      `For outsourced work, the unit should also identify the role boundary. A Philippines-based specialist may prepare evidence, classify an item, or draft a response, while an owner decides whether the business will make a commitment. Treating preparation and approval as one unit makes it impossible to tell whether a delay came from incomplete work, an unavailable decision-maker, or an intentionally held control.`,
    ], rows: [{ label: 'Required unit', value: `One observable ${focus} case with a start point and disposition`, source: 'NIST Cybersecurity Framework 2.0' }, { label: 'Required period', value: 'A stated review window with excluded cases recorded', source: 'ILO Working from Home Report' }] },
    { heading: 'What a defensible sample looks like', paragraphs: [
      `A sample should represent the work that actually arrives, not only the easiest items. Separate routine cases from urgent, incomplete, sensitive, and reopened cases. If the review includes only clean examples, it measures the quality of selection rather than the quality of ${focus}. Keep the denominator visible and explain why any case was excluded.`,
      `A small team does not need a complicated statistical program to learn from a queue. It does need consistent labels. For each sampled case, record the input quality, evidence checked, action prepared, decision boundary reached, elapsed time, and defect category. That record supports bounded interpretation: it can show where the process is failing, but it cannot prove that one staffing arrangement caused the result.`,
    ], rows: [{ label: 'Minimum sample fields', value: 'Input, evidence, action, owner, elapsed time, exception, outcome', source: 'CIS Controls v8' }, { label: 'Interpretation limit', value: 'Descriptive evidence supports process decisions; it is not causal proof', source: 'This review methodology' }] },
    { heading: 'Inputs, context, and confounders', paragraphs: [
      `The same ${focus} result can mean different things when the input conditions differ. A queue may age because demand rose, because requests became more complex, because the owner changed the approval rule, or because the available review window narrowed. Record those contextual changes rather than assigning every variance to individual performance.`,
      `Time-zone work adds a measurable handoff condition. Note when an item became ready, when it entered the review window, and when the next owner could act. This separates production time from waiting time. It also avoids a common mistake: comparing a daytime queue with an overnight queue as if both had identical access to decisions, clarifications, and source systems.`,
    ], rows: [{ label: 'Context variables', value: 'Demand, complexity, review availability, handoff timing, and policy changes', source: 'ILO Working from Home Report' }, { label: 'Security context', value: 'Data access and purpose must remain limited to the work being assessed', source: 'ICO Data Protection Principles' }] },
    { heading: 'Decision rules and escalation boundaries', paragraphs: [
      `A review becomes operationally useful when it states what happens next at each threshold. If evidence is complete and the action is reversible, the specialist may prepare the next step. If the request changes money, access, legal position, customer obligation, or sensitive data exposure, stop and route it to the named owner. Thresholds should be written in observable terms, not in vague instructions such as “use good judgement.”`,
      `Escalation should carry the evidence needed to decide. Include the original request, the relevant record, what was checked, what remains uncertain, and the decision required. This reduces repeated questions and lets the owner distinguish a true urgent case from a request that is merely inconvenient. The route should also state what the specialist may do while waiting, such as preserve a draft or mark the case pending.`,
    ], rows: [{ label: 'Routine disposition', value: 'Prepare, document, and queue for the approved review step', source: 'NIST SP 800-53 Revision 5' }, { label: 'Hard stop', value: 'Escalate changes with financial, legal, privacy, access, or customer impact', source: 'CISA Secure Our World' }] },
    { heading: 'Limitations and what the evidence cannot show', paragraphs: [
      `This review is bounded by the quality and scope of public guidance. The named sources provide control principles, working-condition context, or security practices; they do not provide a universal benchmark for every small business or every Philippines-based team. Local law, contract terms, sector requirements, and the sensitivity of the records can change the appropriate control.`,
      `A process measure also has blind spots. A low defect rate may reflect strong work, easy inputs, or under-reporting. A longer elapsed time may reflect careful review rather than poor execution. Treat the measure as one piece of evidence and compare it with source completeness, exception quality, rework, and owner decisions. When the evidence conflicts, narrow the claim and gather another period of observations.`,
    ], rows: [{ label: 'Primary limitation', value: 'Public guidance is transferable context, not a company-specific causal estimate', source: 'This review methodology' }, { label: 'Quality safeguard', value: 'Pair throughput with accuracy, evidence completeness, rework, and escalation quality', source: 'FTC Data Security' }] },
    { heading: 'Conclusion for owners and operators', paragraphs: [
      `The practical conclusion is narrower than “delegate more.” A sound ${focus} model makes the work observable, measures the right unit, preserves the evidence, and keeps consequential decisions with an accountable owner. That design gives a small business a way to expand repeatable support while learning where ambiguity or risk is accumulating.`,
      `Start with one defined queue and one review period. Publish the scope, access boundary, sample fields, escalation route, and interpretation limits before judging the result. After the period ends, change one rule at a time and preserve the old evidence. This makes improvement traceable and keeps a new exception from silently becoming permanent authority.`,
    ], rows: [{ label: 'Recommended first step', value: `Run one bounded review period for ${focus} and preserve the evidence trail`, source: 'NIST Cybersecurity Framework 2.0' }, { label: 'Success condition', value: 'Owners can explain what was measured, what changed, and what remains uncertain', source: 'NIST SP 800-61 Revision 2' }] },
  ];
  return { ...base, sections: [...base.sections, ...extra] };
};

const aug14Topic = (slug: string, title: string, excerpt: string, cluster: string, stat: string, focus: string, related: readonly string[]): ResearchPost => {
  const base = aug13Topic(slug, title, excerpt, cluster, stat, focus, related);
  const distinct: Record<string, ResearchSection[]> = {
    'review-window-coverage': [{ heading: 'Coverage is not the same as availability', paragraphs: ['A review window is covered only when ready items can reach an authorised decision-maker during the period being measured. A team may have many working hours and still have weak coverage if the person who can approve a change is unavailable, the source system is closed, or the handoff arrives after the decision window. Record both the time an item became ready and the first time a valid decision could be made.', 'Compare ready-item volume with decision capacity by review period, not with total logged-in time. This distinction helps owners see whether a queue needs clearer cutoffs, an alternate approver, or better preparation. It also prevents a simplistic conclusion that a delayed item reflects poor effort when the actual constraint was access to a decision.'], rows: [{ label: 'Coverage unit', value: 'Ready item matched to an authorised review interval', source: 'ILO Working from Home Report' }, { label: 'Common confounder', value: 'Production hours counted as decision capacity', source: 'This review methodology' }] }],
    'input-completeness-baseline': [{ heading: 'Completeness must be tested against the next decision', paragraphs: ['An input is complete for a purpose, not complete in the abstract. A request to prepare a draft may need a source record, audience, deadline, and owner; a request that could change a customer record may also need the authoritative identifier and evidence for the proposed change. List the fields required for the next safe step, then mark missing information rather than filling gaps with plausible assumptions.', 'A baseline should preserve the first version of the request and the clarification trail. Reviewers can then distinguish a weak intake from a careful preparation that exposed an ambiguity. The useful outcome is not a perfect form. It is a repeatable way to decide whether work can proceed, pause, or escalate without disguising uncertainty.'], rows: [{ label: 'Baseline question', value: 'Does the request contain the evidence needed for the next authorised step?', source: 'NIST SP 800-53 Revision 5' }, { label: 'Do not infer', value: 'Missing identity, authority, deadline, or source facts', source: 'This review methodology' }] }],
    'reversible-action-boundaries': [{ heading: 'Reversibility needs a recovery test', paragraphs: ['An action is not meaningfully reversible merely because a button offers an undo option. The owner should know what state can be restored, how quickly, which downstream systems may already have copied the change, and who is accountable if recovery fails. A draft, proposed record change, or unsent reply may be low consequence; a sent commitment or access change may not be.', 'Document reversibility alongside consequence and approval. This gives a specialist a clear preparation boundary without turning “reversible” into blanket permission. When the recovery path is uncertain, preserve the proposal and route it to the owner. The evidence should show the original state, proposed state, and decision required.'], rows: [{ label: 'Recovery test', value: 'State the restoration path, time, owner, and downstream effects', source: 'NIST Cybersecurity Framework 2.0' }, { label: 'Safe default', value: 'Prepare a proposal when recovery cannot be demonstrated', source: 'CISA Secure Our World' }] }],
    'queue-denominator-integrity': [{ heading: 'The denominator is part of the finding', paragraphs: ['A rate without its population is easy to misread. If reopened cases, incomplete requests, or escalated items are excluded, the reported result may describe only the cleanest work. Keep an inclusion rule, exclusion reason, and final disposition for every sampled item. A separate view of excluded work can reveal where the process is creating avoidable ambiguity.', 'Denominator integrity does not require pretending that every case is comparable. It requires making the comparison explicit. Report routine, sensitive, reopened, and owner-held populations separately when their evidence or consequence differs. That makes a small sample more honest and gives the next review period a stable basis for comparison.'], rows: [{ label: 'Required denominator fields', value: 'Eligible population, exclusions, reopenings, and final disposition', source: 'CIS Controls v8' }, { label: 'Interpretation limit', value: 'A clean-case rate is not a queue-wide quality rate', source: 'This review methodology' }] }],
    'source-recency-interpretation': [{ heading: 'Freshness is claim-dependent', paragraphs: ['A recent source is not automatically a better source for every claim. A legal or regulatory statement may require the current edition, while a foundational research finding may remain useful if its population and method fit the question. Record publication date, update date, observation period, population, and the specific claim supported. This prevents a new commentary page from displacing stronger primary evidence simply because it is newer.', 'For an operational brief, distinguish what the source observed from what the owner wants to decide. A source about remote-work conditions can provide context for scheduling or handoffs, but it cannot establish the performance of one particular team. State the transfer explicitly and preserve the uncertainty rather than converting context into a benchmark.'], rows: [{ label: 'Freshness test', value: 'Current enough for the claim, jurisdiction, population, and decision', source: 'NIST Cybersecurity Framework 2.0' }, { label: 'Source boundary', value: 'Context does not become a company-specific causal estimate', source: 'This review methodology' }] }],
    'handoff-state-transitions': [{ heading: 'A handoff is an event, not a message', paragraphs: ['A useful handoff records a state change: ready to review, waiting for evidence, returned for clarification, approved for execution, or closed. A message that says “done” cannot show which state was reached or what the next owner must verify. Capture the triggering event, evidence location, timestamp, and accountable owner for each transition.', 'State labels should be few enough to apply consistently and specific enough to expose waiting. If a case moves backward, record why. Reopened work may indicate changed requirements, missing source material, or an overconfident first disposition. Treat that information as a process signal, not as an individual failure without examining the conditions around the handoff.'], rows: [{ label: 'Transition minimum', value: 'Prior state, new state, event, evidence, owner, and time', source: 'NIST SP 800-61 Revision 2' }, { label: 'Reopen signal', value: 'Changed requirement, missing evidence, or incorrect disposition', source: 'This review methodology' }] }],
    'sensitive-case-segmentation': [{ heading: 'Segmentation follows consequence', paragraphs: ['Sensitive-case segmentation should be based on what could happen if the case is mishandled, not on how urgent or important the requester sounds. Privacy exposure, financial movement, access changes, legal commitments, and promises to customers deserve explicit routes because the cost of an incorrect preparation can exceed the value of speed. The label should explain the reason for the route.', 'Use a small set of observable triggers and review borderline cases. An assistant may gather evidence or draft a response while the owner decides the consequential step. Overly broad labels create noise; overly narrow labels hide risk. Review false positives and false negatives separately so the routing rule can improve without weakening the hard stops.'], rows: [{ label: 'Segmentation basis', value: 'Potential consequence, uncertainty, and required authority', source: 'FTC Data Security' }, { label: 'Owner route', value: 'Privacy, money, access, legal, and customer commitments', source: 'NIST SP 800-53 Revision 5' }] }],
    'record-correction-confidence': [{ heading: 'Confidence comes from agreement', paragraphs: ['A proposed correction deserves stronger confidence when independent source records agree, the records are recent enough for the decision, the identity match is unambiguous, and the downstream consequence is limited. One matching field is not enough when names, accounts, or organisations can overlap. Record the source used, the fields compared, and the unresolved conflict.', 'Confidence should control the next action, not merely decorate a dashboard. High-confidence, low-consequence changes may be prepared for owner review; conflicting evidence should remain a proposal with the discrepancy attached. If the correction would affect access, money, a customer commitment, or a legal record, use a stricter threshold regardless of how plausible it appears.'], rows: [{ label: 'Confidence inputs', value: 'Source agreement, recency, identity match, ambiguity, and consequence', source: 'CIS Controls v8' }, { label: 'Hard stop', value: 'Conflicting evidence or material downstream impact', source: 'This review methodology' }] }],
    'exception-severity-calibration': [{ heading: 'Severity is a routing decision', paragraphs: ['Severity labels are useful when they change what happens next. Describe consequence, urgency, uncertainty, and reversibility separately before assigning a route. A low-urgency case may still be high consequence; a highly urgent request may be routine if the evidence and authority are clear. Combining those dimensions into one intuitive label hides the reason for escalation.', 'Calibrate labels with examples from completed work and review disagreements. The purpose is not to produce a universal score. It is to help a small team agree when an assistant can continue preparing, when a manager must decide, and when work should pause to protect a record or person.'], rows: [{ label: 'Severity dimensions', value: 'Consequence, urgency, uncertainty, and reversibility', source: 'NIST Cybersecurity Framework 2.0' }, { label: 'Calibration method', value: 'Compare labelled examples and document disagreement reasons', source: 'This review methodology' }] }],
    'access-purpose-evidence': [{ heading: 'Permission requires a purpose record', paragraphs: ['An access review is stronger when it connects each permission to a concrete task, resource, owner, and review period. “Needed for support” is too broad to show whether a folder, export, or administrative role is justified. Name the work product, the minimum action required, and the person who can approve expansion or removal.', 'Purpose evidence also helps when work changes. If a queue closes or the assistant moves to a different scope, the owner can see which access has lost its justification. Record exceptions and temporary access separately, with an expiry or review point. This turns least privilege into an observable operating decision rather than a one-time assurance.'], rows: [{ label: 'Purpose record', value: 'Task, resource, minimum action, owner, and review or expiry point', source: 'CIS Controls v8' }, { label: 'Change trigger', value: 'Queue closure, role change, or scope expansion', source: 'NIST SP 800-53 Revision 5' }] }],
  };
  const extra: ResearchSection = { heading: 'Measurement design for a small operating team', paragraphs: [
    `A small team should choose measures that can be collected from ordinary work without creating a second administrative burden. For ${focus}, that means recording the request, the evidence available at intake, the preparation completed, the decision owner, and the final disposition. The record should be sufficient for a later reviewer to reconstruct the case without relying on memory or a private chat.`,
    `Interpret the result at the level the observation supports. One review period can identify missing fields, repeated clarification needs, or a risky authority boundary. It cannot establish a universal benchmark for outsourced work, prove that a Philippines-based arrangement caused an outcome, or substitute for legal, privacy, security, or employment advice. Preserve the raw observations so a later period can test whether a change actually helped.`,
  ], rows: [{ label: 'Minimum record', value: 'Request, input quality, evidence, prepared action, owner, disposition', source: 'CIS Controls v8' }, { label: 'Claim boundary', value: 'Process observations support local improvement, not universal causal claims', source: 'This review methodology' }] };
  return { ...base, sections: [...base.sections, ...(distinct[slug] ?? []), extra] };
};

